import{_ as t,o,c as d,a0 as a}from"./chunks/framework.Bmhw_dvp.js";const p=JSON.parse('{"title":"主题系统实现","description":"","frontmatter":{},"headers":[],"relativePath":"advanced/theme-system.md","filePath":"advanced/theme-system.md","lastUpdated":1790783629000}'),c={name:"advanced/theme-system.md"};function r(s,e,l,i,n,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="主题系统实现" tabindex="-1">主题系统实现 <a class="header-anchor" href="#主题系统实现" aria-label="Permalink to &quot;主题系统实现&quot;">​</a></h1><p>本页说明主题系统的内部运作方式：主题状态存在哪里、颜色怎样从单个种子色派生出来、玻璃效果由哪些 CSS 变量驱动，以及在自定义背景下文字颜色如何自动调整。</p><h2 id="状态模型-themestore" tabindex="-1">状态模型（themeStore） <a class="header-anchor" href="#状态模型-themestore" aria-label="Permalink to &quot;状态模型（themeStore）&quot;">​</a></h2><p><code>themeStore</code> 是基于 zustand 的状态仓库，负责保存所有主题设置。它通过 zustand 的 persist 中间件，把全部主题状态持久化到 localStorage，key 为 <strong><code>zcontrol-theme-storage</code></strong>。核心字段与默认值见下表。</p><table tabindex="0"><thead><tr><th>字段</th><th>默认值</th><th>说明</th></tr></thead><tbody><tr><td><code>sourceColor</code></td><td><code>#0066cc</code></td><td>Monet 种子色</td></tr><tr><td><code>mode</code></td><td><code>&#39;light&#39;</code></td><td><code>auto / light / dark</code>；<code>isDark</code> 是其物化值</td></tr><tr><td><code>colorIntensity</code></td><td><code>100</code></td><td>种子色与中性基底的混合比例</td></tr><tr><td><code>radius</code></td><td><code>&#39;medium&#39;</code></td><td>预设 none 0 / small 8 / medium 16 / large 28 px</td></tr><tr><td><code>glassStrength</code> / <code>glassBlur</code></td><td><code>0.6</code> / <code>12</code></td><td>玻璃透明度 / 模糊度</td></tr><tr><td><code>backgroundImage</code></td><td><code>null</code></td><td>URL 或 base64 dataURL（上传限 5MB）</td></tr><tr><td><code>backgroundBlur</code> / <code>listenTogetherBlur</code></td><td><code>13</code> / <code>0</code></td><td>通用背景模糊 / 一起听独立模糊</td></tr><tr><td><code>backgroundWhiteOverlay</code> / <code>BlackOverlay</code></td><td><code>0</code></td><td>白/黑遮罩强度</td></tr><tr><td><code>customColors</code></td><td><code>[]</code></td><td>收藏色板，上限 24 条</td></tr></tbody></table><p>切换深浅色请调用 <code>setMode</code> 或 <code>setDark</code>，不要直接 <code>set({isDark})</code>。<code>isDark</code> 是从 <code>mode</code> 派生出来的值（<code>mode</code> 为 <code>auto</code> 时由 matchMedia 物化），直接写它会破坏 <code>mode</code> 的一致性，auto 判定随之失效。</p><h3 id="auto-模式物化" tabindex="-1">auto 模式物化 <a class="header-anchor" href="#auto-模式物化" aria-label="Permalink to &quot;auto 模式物化&quot;">​</a></h3><p>auto 模式指跟随系统深浅色。这一节说明系统偏好如何落到 <code>isDark</code> 上。</p><p>当 <code>mode === &#39;auto&#39;</code> 时，ThemeProvider 会监听 <code>(prefers-color-scheme: dark)</code> 的 change 事件，收到变化就直接 <code>setState({ isDark })</code> 完成物化。消费方只读 <code>isDark</code>，因此感觉不到 auto 切换的过程。非 auto 模式下不挂这个监听。</p><h2 id="material-you-动态主题" tabindex="-1">Material You 动态主题 <a class="header-anchor" href="#material-you-动态主题" aria-label="Permalink to &quot;Material You 动态主题&quot;">​</a></h2><p>Material You 是从单一种子色派生整套配色的设计规范。种子色交给 <code>@material/material-color-utilities</code> 的 <code>themeFromSourceColor</code> 后，会生成浅色与深色两套完整的配色方案。</p><p>每套方案输出 27 个 <code>--md-sys-color-*</code> 角色，以及 surface-container 三档（neutral 色调：深色 12/17/22、浅色 94/92/90）和 primary/secondary/tertiary 色阶（13 档 tone）。两套方案按「种子色 + 强度」记忆化缓存，供对比度判定复用。传入非法 hex 时回退到默认方案。</p><h2 id="颜色强度" tabindex="-1">颜色强度 <a class="header-anchor" href="#颜色强度" aria-label="Permalink to &quot;颜色强度&quot;">​</a></h2><p>颜色强度控制种子色与中性基底混合的比例。数值越低，界面越接近中性灰，种子色的存在感越弱。</p><p>用户选定的种子色，会与深浅各自的中性基底在 sRGB 空间逐通道线性插值（与 <code>color-mix(in srgb)</code> 同义）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SEED_MIX_BASE = { light: &#39;#f3f1f7&#39;, dark: &#39;#17161b&#39; }</span></span>\n<span class="line"><span>effectiveSeed = mix(seed, base, intensity / 100)</span></span></code></pre></div><p>强度为 100 时直接返回纯种子色，这是默认值，与未引入强度功能时的表现一致。浅色与深色两套方案分别用各自的基底合成，这样在低强度下派生色依然与背景协调。</p><h2 id="文字对比度自适应" tabindex="-1">文字对比度自适应 <a class="header-anchor" href="#文字对比度自适应" aria-label="Permalink to &quot;文字对比度自适应&quot;">​</a></h2><p>自定义背景会改变文字下方的实际底色，而玻璃面板又有自己的底色，单一的全局判定无法同时覆盖这两类页面。因此实现上分成三个作用域的 CSS 变量分别处理。</p><table tabindex="0"><thead><tr><th>变量组</th><th>判定依据</th><th>消费方</th></tr></thead><tbody><tr><td>根节点（无作用域）</td><td>scheme 原生值，<strong>永不切换</strong></td><td>弹窗（portal 到 body）、硬编码色组件</td></tr><tr><td><code>--lt-raw-*</code></td><td>原始背景（底色 → 壁纸 → 遮罩）</td><td>音乐壳等文字直坐壁纸的页面</td></tr><tr><td><code>--lt-glass-*</code></td><td>含玻璃层的有效背景（<code>surface-container × glassStrength</code>）</td><td>顶栏、播放页、迷你条等主题驱动玻璃面</td></tr></tbody></table><p><code>--lt-raw-*</code> 与 <code>--lt-glass-*</code> 都要按 UI 的渲染顺序合成背景色，合成算法见「合成算法（<code>bgContrast.ts</code>）」一节。</p><h3 id="合成算法-bgcontrast-ts" tabindex="-1">合成算法（<code>bgContrast.ts</code>） <a class="header-anchor" href="#合成算法-bgcontrast-ts" aria-label="Permalink to &quot;合成算法（`bgContrast.ts`）&quot;">​</a></h3><p><code>bgContrast.ts</code> 负责从背景算出最终的文字底色。计算时按 UI 的渲染顺序，在 sRGB 空间逐通道叠加各层：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>底色 → 壁纸（opacity 混合，32×32 canvas 降采样平均色） → 白遮罩 → 黑遮罩 → 玻璃面板层</span></span></code></pre></div><p>合成过程中有三处需要留意。</p><ul><li>壁纸平均色用 32×32 canvas（<code>willReadFrequently</code>）求均值，结果按 URL 缓存（包括失败的情况）。背景高斯模糊不改变平均亮度，因此不触发重采样。</li><li>玻璃层必须计入。深色模式下的深玻璃会压暗文字底色，不计入就会误判。</li><li>判定规则是：对侧 scheme 文字色的对比度要比当前侧<strong>高出 1.0</strong>（切换幅度阈值）才切换，避免在临界点反复抖动。覆盖的变量只有四个中性文字色：<code>on-surface / on-surface-variant / outline / outline-variant</code>。</li></ul><h2 id="主题编辑栏" tabindex="-1">主题编辑栏 <a class="header-anchor" href="#主题编辑栏" aria-label="Permalink to &quot;主题编辑栏&quot;">​</a></h2><p>主题编辑栏是设置主题的界面。主题菜单打开后，一级左栏即展开；Zen 主题编辑器分为五段：模式切换（auto ✨ / 浅色 ☀ / 深色 🌙）、取色页（SV 二维区 + 色相条 + Hex）、颜色强度滑块、预设 10 色网格 + 收藏色板、实时预览。</p><p>收藏色板的所有操作都遵循单向数据流，没有隐式副作用。</p><ul><li>点击圆点表示应用该颜色，只做切换，不触碰色板。</li><li>取色页的「收藏」表示新增，「更新收藏」表示原位更新被编辑的条目（只有从收藏色进入取色页时才出现）；当前色已在收藏中时，两个按钮都禁用。</li><li>🗑 只把颜色移出收藏板，不改变正在使用的主题色。</li></ul><h2 id="玻璃变量与工具类" tabindex="-1">玻璃变量与工具类 <a class="header-anchor" href="#玻璃变量与工具类" aria-label="Permalink to &quot;玻璃变量与工具类&quot;">​</a></h2><p>玻璃拟态（半透明加背景模糊的视觉效果）由 ThemeProvider 注入的一组派生变量驱动，所有玻璃组件都引用同一套工具类：<code>.glass</code> / <code>.glass-strong</code> / <code>.glass-card</code> / <code>.glass-bg</code>。各变量的计算公式见下表。</p><table tabindex="0"><thead><tr><th>变量</th><th>公式</th></tr></thead><tbody><tr><td><code>--glass-blur</code></td><td><code>${glassBlur}px</code></td></tr><tr><td><code>--glass-blur-strong</code></td><td><code>min(40, glassBlur + 4)px</code></td></tr><tr><td><code>--glass-blur-mask</code></td><td><code>glassBlur × 0.4</code>（弹窗蒙层取 40%）</td></tr><tr><td><code>--glass-bg</code></td><td><code>rgba(surface-container-rgb, glassStrength)</code></td></tr><tr><td><code>--glass-border</code></td><td><code>rgba(rgb, min(1, strength + 0.15))</code></td></tr></tbody></table><p><code>:root</code> 中的静态兜底值，保证 ThemeProvider 挂载之前（例如登录卡片的首帧）这些变量就已经生效。用 lightningcss 压缩时要注意：<code>-webkit-backdrop-filter</code> 必须写在标准属性之前，否则压缩去重后会保留最后一条，导致 Safari 失效。</p><h2 id="哪些动画会破坏毛玻璃" tabindex="-1">哪些动画会破坏毛玻璃 <a class="header-anchor" href="#哪些动画会破坏毛玻璃" aria-label="Permalink to &quot;哪些动画会破坏毛玻璃&quot;">​</a></h2><p>Backdrop Root 是浏览器划分模糊采样区域的边界，落在它之外的元素不会被 <code>backdrop-filter</code> 模糊到。带 <code>transform</code>、<code>filter</code> 这类属性的元素会成为 Backdrop Root，这是毛玻璃失效最常见的原因。以下约定都来自实际故障复盘。</p><ul><li>入场动画的 <code>animation-fill-mode</code> 一律用 <code>backwards</code>，不要用 <code>both</code> 或 <code>forwards</code>。原因是这两个值会让元素在动画结束后永久保留 <code>transform</code>，成为 Backdrop Root，后代玻璃层的 <code>backdrop-filter</code> 采样不到这个元素之外的背景，模糊直接失效——封面页毛玻璃丢失就是这个原因。终帧与自然状态一致即可；只有 exit 动画（结束时元素本来就要消失）才适合用 <code>forwards</code>。</li><li>弹出面板的定位不要依赖 <code>transform</code>。用 <code>-translate-x-1/2</code> 居中时，如果 keyframes 在动画全程接管 <code>transform</code>，动画期间的偏移会丢失，结束时还会跳位。居中与偏移请改用 <code>left/top</code> 加负 margin，或用 <code>right</code> 定位；Dropdown 组件则用 fixed 定位加数值内联定位，并按 placement 覆写 <code>transformOrigin</code>。</li><li><code>filter</code> 同样会制造 Backdrop Root。<code>filter: drop-shadow(...)</code> 这类效果要分发到子元素上，不能写在包含 glass-card 弹窗的容器上——播放队列弹窗模糊丢失就是这个原因。</li><li><code>overflow-y-auto</code> 会连带产生 <code>overflow-x: auto</code>。滚动容器会裁掉 absolute 悬出的弹窗，因此不要让滚动容器包住弹窗锚点，或者把弹窗改成 fixed / sheet。</li><li>absolute 背景覆盖层必须加上 <code>pointer-events-none</code>。定位元素绘制在非定位流内容之上，冰霜层或底色层如果没有 <code>pointer-events-none</code>，就会拦截同一容器内交互元素的点击。</li><li>滑动条挂 <code>touch-slider</code>（<code>touch-action: none</code>），防止触屏拖动时连带页面滚动。只在 hover 时显形的控件挂 <code>lt-touch-visible</code>（<code>pointer: coarse</code> 下常显）。</li></ul><h3 id="精简动画" tabindex="-1">精简动画 <a class="header-anchor" href="#精简动画" aria-label="Permalink to &quot;精简动画&quot;">​</a></h3><p>精简动画开关用于降低界面上的动态效果，减少视觉干扰。开启时，工具会把当前值快照到 <code>_reducedMotionPrev</code>（不持久化）并锁定为 <code>glassStrength: 1, glassBlur: 0, backgroundBlur: 0, listenTogetherBlur: 0</code>；关闭时从快照恢复。</p><p><code>[data-reduced-motion=&#39;true&#39;]</code> 挂在 Layout 根容器上，用来裁剪动画。<code>[data-no-hover-transform=&#39;true&#39;]</code> 挂在 <strong>document.body</strong> 上（portal 组件同样生效），通过覆盖 Tailwind 的 translate / scale 变量，全局关闭 hover 位移。</p><h2 id="自定义背景渲染-layout-tsx" tabindex="-1">自定义背景渲染（Layout.tsx） <a class="header-anchor" href="#自定义背景渲染-layout-tsx" aria-label="Permalink to &quot;自定义背景渲染（Layout.tsx）&quot;">​</a></h2><p>自定义背景由 <code>Layout.tsx</code> 渲染。各图层的堆叠顺序如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>背景层（fixed z-0） → 白遮罩 → 黑遮罩 → 内容层（relative z-auto）</span></span></code></pre></div><ul><li>默认壁纸是 <code>/Nacho3.jpg</code>。自定义壁纸的 opacity 直接生效，默认壁纸的 opacity 封顶 0.85。</li><li><code>transform</code> 的组合顺序固定为 <code>translate(x/2%, y/2%) scale(s) rotate(r)</code>。translate 必须放在前面，避免缩放中心扩张抵消偏移；百分比除以 2 是为了把最大偏移限制在 ±50%。位置不用 <code>background-position</code> 实现，因为百分比在 cover 下某方向无溢出时不生效。</li><li>内容层用 <code>z-auto</code>，不创建层叠上下文，这样 glass-card 的 backdrop-filter 才能跨层采样到 z-0 的背景图。</li><li>模糊值随房间模式切换：<code>roomMode === &#39;listen-together&#39; ? listenTogetherBlur : backgroundBlur</code>。</li></ul>',44)])])}const g=t(c,[["render",r]]);export{p as __pageData,g as default};
